-- the fields it reads:
var event:    one Event,

var issue: lone Issue,

var pullRequest: lone PullRequest

one sig Who { var session: lone Session, var predecessor: lone Session, var addressed: set Session }

var worksOn:      lone Campaign,

var memberIssues: set Issue,       -- ground truth

one sig Target { var agent: lone Agent }

/* THE PLANNER'S, and only the planner's: a worker's own session does not
   answer its own BLOCKED, and a session on another sub-issue does not either.
   Where the answer is preference, scope or a destructive stake, the planner
   asks the owner with AskUserQuestion and records what they say as this same
   DECISION, so the owner decides through the planner and has no event of
   their own. A planner's own BLOCKED is that case: its session is the one
   that asks. When the planner answers is `answerInTurn`'s, in checks.als. */
pred decide[a: Agent] {
  a in Live
  a in Waiting
  a.task in Who.session.worksOn.memberIssues
  Who.session in livePlannersOn[a.task].peer
  Waiting' = Waiting - a
  Reported' = Reported and Asked' = Asked and Answered' = Answered
  keepLife and keepReview and keepShutdown and keepLaunched and keepContext
  Now.event = Decide and Now.issue = a.task and Target.agent = a
}

-- what it names:
/* The planner of a sub-issue, while it runs: a delegate's launch, a
   `blocked` and a `decide` all need one, and this is the one statement of
   which. */
fun livePlannersOn[i: Issue]: set Agent { plannerAgents & Live & task.i }

pred keepLife     { Live' = Live and LocalOnly' = LocalOnly and PushedToRemote' = PushedToRemote and Confirmed' = Confirmed and keepStopped }

pred keepReview   { Reviewed' = Reviewed }

pred keepShutdown { StandDownTaken' = StandDownTaken and Retired' = Retired }

pred keepLaunched     { Launched' = Launched }

/* Split out because two events move it and every other keeps it, and the six
   preds that spell the life bits one by one need it named. */
pred keepContext  { Compacted' = Compacted }

-- the fields it reads:
task:     one Issue,

one sig Who { var session: lone Session, var predecessor: lone Session, var addressed: set Session }

var worksOn:      lone Campaign,

var memberIssues: set Issue,       -- ground truth

/* Set when the agent IS a campaign session working its own claim. A delegate
     is named at launch; a session's own claim is named by nothing anybody else
     chose, which is why only it needs a record. */
  peer:     lone Session

var event:    one Event,

var issue: lone Issue,

one sig Target { var agent: lone Agent }

/* role-planner.md step 7: in the turn a BLOCKED reaches the planner, its first act
   is the DECISION -- its own, or the owner's answer to AskUserQuestion -- and
   nothing else runs first. "Reaches" covers a planner starting with one
   already standing, so it is read off the state and not off `Blocked`.
   WHAT IT COSTS: it holds back every event while a worker waits, not the
   planner's alone, so a death or a limit stop during the wait is excluded
   rather than examined. So is the one trace the review found where the
   planner cannot answer: a `RemoveMember` unlinking the sub-issue while its
   worker waits, which leaves `decide` with no taker. */
pred answerInTurn {
  always (some waitingOnPlanner implies (Now.event = Decide and Target.agent in waitingOnPlanner))
}

-- what it names:
/* Live agents waiting on a BLOCKED whose sub-issue has a planner running. */
fun waitingOnPlanner: set Agent { { a: Waiting & Live | some livePlannersOn[a.task] } }

-- the fields it reads:
var event:    one Event,

one sig Target { var agent: lone Agent }

/* A prompt to verify, never the verification, so this event writes NOTHING
   but the claim itself. A REPORT names a pull request, so it is the
   worker's. */
pred report[a: Agent] {
  a in Live and a not in Stopped and a.role = Worker
  Reported' = Reported + a
